    MessagePattern(Msg.msg_17b7c023b762, "be", "Налада агульная для прылады. Пры выключэнні сінхранізацыя спыняецца, захаваная музыка не выкарыстоўваецца. Прайграванне анлайн і падрыхтоўка наступнага трэка хвалі працягваюць працаваць."),
