    MessagePattern(Msg.msg_af72c5eb8791, "be", "На K4811 адкрывайце панэль кароткім свайпам ад сярэдзіны левага або правага краю ці ад цэнтра ніжняга краю. Зона жэста нябачная і займае толькі невялікую частку краю."),
    MessagePattern(Msg.msg_af72c5eb8791, "en", "On K4811, use a short swipe from the middle of the left or right edge, or the center of the bottom edge. The gesture area is invisible and covers only a small part of the edge."),
    MessagePattern(Msg.msg_af72c5eb8791, "fr", "Sur K4811, ouvrez le panneau par un court balayage depuis le milieu du bord gauche ou droit, ou le centre du bord inférieur. La zone du geste est invisible et n’occupe qu’une petite partie du bord."),
    MessagePattern(Msg.msg_af72c5eb8791, "de", "Öffne die Seitenleiste auf K4811 mit einem kurzen Wischen von der Mitte des linken oder rechten Randes oder der Mitte des unteren Randes. Der unsichtbare Gestenbereich belegt nur einen kleinen Teil des Randes."),
    MessagePattern(Msg.msg_af72c5eb8791, "kk", "K4811 жүйесінде панельді сол не оң жақ шеттің ортасынан немесе төменгі шеттің ортасынан қысқа сырғытумен ашыңыз. Қимыл аймағы көрінбейді және шеттің шағын бөлігін ғана қамтиды."),
    MessagePattern(Msg.msg_af72c5eb8791, "ru", "На K4811 откройте панель коротким свайпом от середины левого или правого края либо от центра нижнего края. Зона жеста невидима и занимает лишь небольшую часть края."),
    MessagePattern(Msg.msg_af72c5eb8791, "es", "En K4811, abre el panel con un deslizamiento corto desde el centro del borde izquierdo o derecho, o del borde inferior. La zona del gesto es invisible y solo ocupa una pequeña parte del borde."),
    MessagePattern(Msg.msg_af72c5eb8791, "uk", "На K4811 відкривайте панель коротким свайпом від середини лівого чи правого краю або від центру нижнього краю. Зона жесту невидима й займає лише невелику частину краю."),
    MessagePattern(Msg.msg_af9d1711a669, "be", "Выберыце папку ў сістэмным акне. Музыка застаецца на сваім месцы, праграма атрымлівае толькі доступ для чытання."),
    MessagePattern(Msg.msg_af9d1711a669, "en", "Choose a folder in the system picker. Your music stays where it is; the app only gets read access."),
    MessagePattern(Msg.msg_af9d1711a669, "fr", "Choisissez un dossier dans le sélecteur système. Votre musique reste à sa place ; l’application n’obtient qu’un accès en lecture."),
