    MessagePattern(Msg.msg_c90dd531a092, "be", "Бягучы трэк, ужо падрыхтаваныя трэкі хвалі і захаваныя файлы захоўваюць сваю якасць. Каб зноў спампаваць усю афлайн-калекцыю, выдаліце яе файлы ў наладах афлайн-кэша і запусціце сінхранізацыю. Лайкі застануцца ў Яндэксе."),
    MessagePattern(Msg.msg_c90dd531a092, "en", "The current track, preloaded My Vibe tracks and downloaded files keep their existing quality. To download your entire offline collection again, clear its files in Offline cache settings and sync again. Your likes on Yandex will remain."),
    MessagePattern(Msg.msg_c90dd531a092, "fr", "Le titre en cours, les titres de Mon mix déjà préchargés et les fichiers téléchargés conservent leur qualité. Pour télécharger à nouveau toute votre collection hors connexion, effacez ses fichiers dans les paramètres du cache hors connexion, puis relancez la synchronisation. Vos mentions J’aime sur Yandex sont conservées."),
    MessagePattern(Msg.msg_c90dd531a092, "de", "Der aktuelle Titel, bereits vorgeladene Titel aus Mein Mix und heruntergeladene Dateien behalten ihre Qualität. Um die gesamte Offline-Sammlung erneut herunterzuladen, lösche ihre Dateien in den Offline-Cache-Einstellungen und starte die Synchronisierung erneut. Deine Likes bei Yandex bleiben erhalten."),
    MessagePattern(Msg.msg_c90dd531a092, "kk", "Қазіргі тректің, толқынның алдын ала жүктелген тректерінің және сақталған файлдардың сапасы өзгермейді. Бүкіл офлайн жинақты қайта жүктеп алу үшін офлайн кэш баптауларында оның файлдарын жойып, синхрондауды іске қосыңыз. Yandex сервисіндегі ұнату белгілері сақталады."),
